// Published reference values are transcribed data, never generated by this model.
import { stepKinetics, saturationPressure, liquidEnthalpy, vaporEnthalpy } from './physics.js';
import { if97Region1, if97Region2, if97SaturationPressure } from './water-properties.js';

const CATS = Object.freeze({
  title: 'B. D. Ganapol, A precision benchmark suite for nuclear reactor point kinetics equations via converged accelerated Taylor series (CATS), 2024',
  url: 'https://arxiv.org/pdf/2406.11822',
});
const IF97 = Object.freeze({
  title: 'IAPWS R7-97(2012), Revised Release on the IAPWS Industrial Formulation 1997',
  url: 'https://iapws.org/technical-guidance/release/IF97-Rev.download',
});
const NIST = Object.freeze({
  title: 'NISTIR 5078, Table 1: Saturation (Temperature)',
  url: 'https://www.nist.gov/document/nistir5078-tab1pdf',
});
const freezeGroups = pairs => Object.freeze(pairs.map(([beta, lambda]) => Object.freeze({beta, lambda})));
// CATS Appendix A, Table A.II. These benchmark configurations are
// independent of the generic plant's assumed prompt generation time (0.0001 s).
export const CATS_TRI_GROUPS = freezeGroups([
  [.000285,.0127], [.0015975,.0317], [.00141,.115],
  [.0030525,.311], [.00096,1.40], [.000195,3.87],
]);
const freezeSamples = rows => Object.freeze(rows.map(Object.freeze));
export const KINETICS_REFERENCES = Object.freeze([
  Object.freeze({ id: 'cats-negative-half-dollar', name: 'CATS TRI −0.5 dollar step',
    groups: CATS_TRI_GROUPS, generationTime: .0005, stepPcm: -375, dt: .00025,
    table: 'Table 2a, printed p.17; parameters Table A.II, printed p.56',
    samples: freezeSamples([[.1,.6989252255707], [1,.6070535656062], [5,.4825530299222],
      [10,.3960776907155], [100,.07158285443859], [200,.01693479165875]]) }),
  Object.freeze({ id: 'cats-negative-one-dollar', name: 'CATS TRI −1 dollar step',
    groups: CATS_TRI_GROUPS, generationTime: .0005, stepPcm: -750, dt: .00025,
    table: 'Table 2b, printed p.17; parameters Table A.II, printed p.56',
    samples: freezeSamples([[.1,.5205642866088], [1,.4333334453006], [5,.3106777684278],
      [10,.2361106507888], [100,.02866764245448], [200,.005590596793349]]) }),
  Object.freeze({ id: 'cats-zigzag', name: 'CATS TRI zigzag reactivity',
    groups: CATS_TRI_GROUPS, generationTime: .0005, waveform:'zigzag', dt: .0001,
    table: 'Table 4 and Eq. 10, printed p.19; parameters Table A.II, printed p.56',
    samples: freezeSamples([[.5,1.721422422085], [1,1.211127414825],
      [1.5,1.892226140394], [2,2.521600530004], [10,12.04710535483]]) }),
]);

// IAPWS release Tables 5 and 15, all three published thermodynamic test states
// for each implemented single-phase region. h/u kJ/kg, s/cp kJ/(kg K), v m³/kg.
export const IF97_REFERENCES = Object.freeze([
  {region:1,T:300,p:3,v:.00100215168,h:115.331273,u:112.324818,s:.392294792,cp:4.17301218},
  {region:1,T:300,p:80,v:.000971180894,h:184.142828,u:106.448356,s:.368563852,cp:4.01008987},
  {region:1,T:500,p:3,v:.00120241800,h:975.542239,u:971.934985,s:2.58041912,cp:4.65580682},
  {region:2,T:300,p:.0035,v:39.4913866,h:2549.91145,u:2411.69160,s:8.52238967,cp:1.91300162},
  {region:2,T:700,p:.0035,v:92.3015898,h:3335.68375,u:3012.62819,s:10.1749996,cp:2.08141274},
  {region:2,T:700,p:30,v:.00542946619,h:2631.49474,u:2468.61076,s:5.17540298,cp:10.3505092},
].map(Object.freeze));
export const NIST_REFERENCES = Object.freeze([
  {T:20,p:.0023393,hL:83.91,hV:2537.4}, {T:25,p:.0031699,hL:104.83,hV:2546.5},
  {T:100,p:.10142,hL:419.17,hV:2675.6}, {T:200,p:1.5549,hL:852.27,hV:2792.0},
  {T:280,p:6.4166,hL:1236.9,hV:2779.9}, {T:300,p:8.5879,hL:1345.0,hV:2749.6},
  {T:350,p:16.529,hL:1670.9,hV:2563.6},
].map(Object.freeze));

/** Run the production kinetics integrator at independently specified benchmark
 * parameters. Right-endpoint reactivity is consistent with backward Euler. */
export function evaluateKineticsReference(reference, dt = reference.dt) {
  if (!Number.isFinite(dt) || dt <= 0 || dt > .05) throw new RangeError('Benchmark step must be in (0, 0.05] s');
  let state = {n:1, precursors: reference.groups.map(() => 1)};
  let time = 0;
  return reference.samples.map(([target, expected]) => {
    // Segment at every published edit time to avoid time-grid interpolation.
    const count = Math.ceil((target - time) / dt - 1e-9);
    const step = (target - time) / count;
    const start = time;
    for (let i = 0; i < count; i++) {
      const end = start + (i + 1) * step;
      // CATS Eq. 10, converted from delta-k/k to pcm. Sample times include
      // all three corners, so no integration step crosses a slope change.
      const rho = reference.stepPcm ?? (end <= .5 ? 750 * end
        : end <= 1 ? -750 * (end - .5) + 375
          : end <= 1.5 ? 750 * (end - 1) : 375);
      state = stepKinetics(state.n, state.precursors, rho, step, reference);
    }
    time = target;
    return {time, reference:expected, measured:state.n};
  });
}

function comparison({reference, measured, tolerance, ...details}) {
  const error = Math.abs(measured - reference);
  return {...details, reference, measured, error, tolerance,
    relativeError: error / Math.abs(reference), pass: Number.isFinite(measured) && error <= tolerance};
}

/** Deterministic published-reference comparisons; no network, clock, or file IO.
 * The caller adds release metadata. This is component verification, not measured
 * plant validation, and is intentionally separate from behavioral plant checks. */
export function runBenchmarks() {
  const checks = [];
  for (const ref of KINETICS_REFERENCES) {
    for (const sample of evaluateKineticsReference(ref)) {
      checks.push(comparison({
        id:`${ref.id}-${sample.time}s`, name:`${ref.name} at ${sample.time} s`, category:'kinetics',
        reference:sample.reference, measured:sample.measured, tolerance:sample.reference * .001,
        units:'n/n₀', source:{...CATS, table:ref.table},
        conditions:`Initial n=1 and equilibrium precursors; no source or feedback; Λ=${ref.generationTime} s; Δt=${ref.dt} s; ${ref.stepPcm !== undefined ? `ρ=${ref.stepPcm} pcm` : 'ρ follows Eq. 10: 0→375→0→375 pcm at t=0,0.5,1,1.5 s, then holds'}.`,
      }));
    }
  }
  const units = {v:'m³/kg',h:'kJ/kg',u:'kJ/kg',s:'kJ/(kg K)',cp:'kJ/(kg K)'};
  for (const ref of IF97_REFERENCES) {
    const measured = (ref.region === 1 ? if97Region1 : if97Region2)(ref.T, ref.p);
    for (const property of Object.keys(units)) {
      checks.push(comparison({
        id:`if97-r${ref.region}-${ref.T}K-${ref.p}MPa-${property}`,
        name:`IF97 region ${ref.region}: ${property}, ${ref.T} K / ${ref.p} MPa`, category:'water-properties',
        reference:ref[property], measured:measured[property], tolerance:Math.abs(ref[property]) * 1e-8,
        units:units[property], source:{...IF97, table:`Table ${ref.region === 1 ? 5 : 15}`},
        conditions:'Direct Gibbs-equation evaluation. Official printed verification values; 1e-8 relative tolerance accommodates table rounding.',
      }));
    }
  }
  for (const [temperatureK, reference] of [[300,.00353658941],[500,2.63889776],[600,12.3443146]]) {
    checks.push(comparison({id:`if97-saturation-${temperatureK}K`, name:`IF97 saturation pressure at ${temperatureK} K`,
      category:'water-properties',reference,measured:if97SaturationPressure(temperatureK),tolerance:reference*1e-8,
      units:'MPa',source:{...IF97,table:'Table 35'},conditions:'Direct region-4 Eq. 30 evaluation; used to generate the production enthalpy table.'}));
  }
  for (const ref of NIST_REFERENCES) {
    const measured = {p:saturationPressure(ref.T),hL:liquidEnthalpy(ref.T)*1000,hV:vaporEnthalpy(ref.T)*1000};
    for (const property of ['p','hL','hV']) {
      checks.push(comparison({id:`nist-production-${ref.T}C-${property}`,
        name:`Production ${property} at ${ref.T} °C`,category:'water-properties',
        reference:ref[property],measured:measured[property],tolerance:ref[property]*.0005,
        units:property === 'p' ? 'MPa' : 'kJ/kg',source:{...NIST,table:`Table 1, ${ref.T} °C row`},
        conditions:'Actual production property function. Saturated pure water; 0.05% tolerance includes IF97/IAPWS-95 differences and printed-table rounding.',
      }));
    }
  }
  const passed = checks.filter(check => check.pass).length;
  return {
    scope:'Published component benchmarks: point-kinetics equations and pure-water properties. Kinetics uses stated fine timesteps and published reactor parameters, not the 50 ms coupled-plant step. No measured plant transient, startup procedure, protection system, or whole-plant validation is claimed.',
    summary:{total:checks.length,passed,failed:checks.length-passed}, checks,
  };
}
